steps.code:
$q = "Cas26Service_CL | where TimeGenerated > ago(30m) | where Customer == 'IIC' | summarize Completed=countif(Component == 'Coordinator' and Stage == 'Completed' and Success == true), Failed=countif(Success == false), LastSeen=max(TimeGenerated) by CorrelationId | summarize Orders=count(), FailedOrders=countif(Failed > 0), Unresolved=countif(Completed == 0 and Failed == 0), LastSeen=max(LastSeen) | extend FailurePercent=iff(Orders > 0, 100.0*FailedOrders/Orders, real(null))"
az monitor log-analytics query --workspace $Demo.LogAnalyticsWorkspaceId --analytics-query $q -o table
if (Get-Variable order -ErrorAction SilentlyContinue) {
    $q = "Cas26Service_CL | where CorrelationId == '$($order.CorrelationId)' | project TimeGenerated, Cloud, Component, Stage, Success, DurationMs, FailureMode | order by TimeGenerated asc"
    az monitor log-analytics query --workspace $Demo.LogAnalyticsWorkspaceId --analytics-query $q -o table
}

az tag update --resource-id $Demo.Ec2RbacArcResourceId --operation Merge --tags CAS26RbacProof=operator-verified
if ($LASTEXITCODE -ne 0) { throw 'The operation failed. Stop and follow the recovery instructions.' }
az resource show --ids $Demo.Ec2RbacArcResourceId --query tags -o json

$RemediationName = 'cas26-onprem-' + (Get-Date -Format 'yyyyMMddHHmmss')
az policy remediation create --resource $TargetId --policy-assignment $AssignmentId --name $RemediationName --resource-discovery-mode ExistingNonCompliant -o json
if ($LASTEXITCODE -ne 0) { throw 'The operation failed. Stop and follow the recovery instructions.' }

if (-not (Get-Variable AwsCanary -ErrorAction SilentlyContinue)) { throw 'Set $AwsCanary to the AWS canary Arc machine name first.' }
az connectedmachine assess-patches --resource-group $Demo.OperationsResourceGroup --name ($Demo.OnPremArcResourceId.Split('/')[-1])
az connectedmachine assess-patches --resource-group $Demo.AwsResourceGroup --name $AwsCanary

$kinds = kubectl --context $Demo.KubernetesContext api-resources --namespaced=true --verbs=list -o name
foreach ($kind in $kinds) { kubectl --context $Demo.KubernetesContext get $kind --namespace cas26-demo --ignore-not-found -o name }
# Review all results and ownership before considering configuration deletion.
